<script>
/* ═══ CAROUSEL ═══ */
(function() {
  const track = document.getElementById('carouselTrack');
  const prevBtn = document.getElementById('carouselPrev');
  const nextBtn = document.getElementById('carouselNext');
  const dotsContainer = document.getElementById('carouselDots');
  const cards = track.querySelectorAll('.product-card');

  if (!track || !prevBtn || !nextBtn || cards.length === 0) return;

  let currentIndex = 0;
  let cardsPerView = 4;
  let cardWidth = 0;

  function calcLayout() {
    const style = getComputedStyle(track);
    const gap = parseInt(style.gap) || 20;
    const firstCard = cards[0];
    cardWidth = firstCard.offsetWidth + gap;

    if (window.innerWidth <= 600) {
      cardsPerView = 1;
    } else if (window.innerWidth <= 900) {
      cardsPerView = 2;
    } else {
      cardsPerView = 4;
    }
  }

  function updateCarousel() {
    calcLayout();
    const totalPages = Math.max(1, cards.length - cardsPerView + 1);
    if (currentIndex >= totalPages) currentIndex = totalPages - 1;
    if (currentIndex < 0) currentIndex = 0;

    track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;

    // Update dots
    dotsContainer.innerHTML = '';
    for (let i = 0; i < totalPages; i++) {
      const dot = document.createElement('button');
      dot.className = 'dot' + (i === currentIndex ? ' active' : '');
      dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
      dot.addEventListener('click', () => {
        currentIndex = i;
        updateCarousel();
      });
      dotsContainer.appendChild(dot);
    }

    prevBtn.style.opacity = currentIndex === 0 ? '0.4' : '1';
    nextBtn.style.opacity = currentIndex >= totalPages - 1 ? '0.4' : '1';
  }

  prevBtn.addEventListener('click', () => {
    if (currentIndex > 0) {
      currentIndex--;
      updateCarousel();
    }
  });

  nextBtn.addEventListener('click', () => {
    const totalPages = Math.max(1, cards.length - cardsPerView + 1);
    if (currentIndex < totalPages - 1) {
      currentIndex++;
      updateCarousel();
    }
  });

  window.addEventListener('resize', updateCarousel);
  updateCarousel();
})();

/* ═══ STORE LOCATOR ═══ */
(function() {
  const zipInput = document.getElementById('zipInput');
  const searchBtn = document.getElementById('searchBtn');
  const resultsContainer = document.getElementById('storeResults');

  const storeData = [
    { name: 'Fresh Pantry — Lincoln Park', address: '2140 N. Halsted St, Chicago, IL 60614', hours: '8am – 9pm Daily', distance: '0.8 mi' },
    { name: 'Fresh Pantry — Wicker Park', address: '1840 W. North Ave, Chicago, IL 60622', hours: '8am – 9pm Daily', distance: '1.4 mi' },
    { name: 'Fresh Pantry — Lakeview', address: '3745 N. Lincoln Ave, Chicago, IL 60613', hours: '8am – 9pm Daily', distance: '2.1 mi' }
  ];

  function performSearch() {
    const zip = zipInput.value.trim();
    if (zip.length < 2) {
      zipInput.style.borderColor = 'var(--orange)';
      setTimeout(() => { zipInput.style.borderColor = ''; }, 1500);
      return;
    }

    resultsContainer.innerHTML = storeData.map(store => `
      <div class="store-card">
        <div class="store-info">
          <h4>${store.name}</h4>
          <p>${store.address} · ${store.hours}</p>
        </div>
        <span class="store-distance">${store.distance}</span>
      </div>
    `).join('');
    resultsContainer.classList.add('visible');
  }

  searchBtn.addEventListener('click', performSearch);
  zipInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') performSearch();
  });
})();

/* ═══ NEWSLETTER ═══ */
(function() {
  const form = document.getElementById('newsletterForm');
  const confirm = document.getElementById('newsletterConfirm');
